import { Routes, Route } from "react-router-dom";
import Main from "./pages/Main";
import AuthPage from "./AuthPage";

function App() {
  return (
    <Routes>
      {/* HOME / MAIN PAGE */}
      <Route path="/" element={<Main />} />

      {/* LOGIN PAGE */}
      <Route path="/login" element={<AuthPage />} />
    </Routes>
  );
}

export default App;
